signed = ssl_sign(concatenate_with_newlines(headers), private_key, 'sha256') signature = { 'keyId': 'sender-fqdn', # The sending server's FQDN; find its public key through OCM API discovery 'algorithm': 'rsa-sha256', 'headers': 'content-length date content-digest host', 'signature': signed, }
